// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Empty } from "@/registry/erbium/ui/empty";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { EmptyHeader, EmptyMedia, EmptyTitle, EmptyDescription } from \"@/registry/erbium/ui/empty\";\nimport { Empty } from \"@/registry/erbium/ui/empty\";\n\nconst Example = (args: {\n  className: string;\n  mediaVariant: \"default\" | \"icon\";\n  title: string;\n  description: string;\n}) => (\n  <Empty className={`w-80 ${args.className}`}>\n    <EmptyHeader>\n      <EmptyMedia variant={args.mediaVariant}>☆</EmptyMedia>\n      <EmptyTitle>{args.title}</EmptyTitle>\n      <EmptyDescription>{args.description}</EmptyDescription>\n    </EmptyHeader>\n  </Empty>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/empty-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import AvatarExample from "./variants/avatar";

const AvatarSource = "import ExampleEmptyAvatar from \"../examples/empty-avatar\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleEmptyAvatar />\n  </div>\n);\n\nexport default Example;\n";

import AvatarGroupExample from "./variants/avatar-group";

const AvatarGroupSource = "import ExampleEmptyAvatarGroup from \"../examples/empty-avatar-group\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleEmptyAvatarGroup />\n  </div>\n);\n\nexport default Example;\n";

import InputgroupExample from "./variants/inputgroup";

const InputgroupSource = "import ExampleEmptyInputGroup from \"../examples/empty-input-group\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleEmptyInputGroup />\n  </div>\n);\n\nexport default Example;\n";

import InputGroupExample from "./variants/input-group";

const InputGroupSource = "import EmptyInputGroup from \"../examples/empty-input-group\";\n\nconst Example = () => <EmptyInputGroup />;\n\nexport default Example;\n";

import OutlineExample from "./variants/outline";

const OutlineSource = "import EmptyOutline from \"../examples/empty-outline\";\n\nconst Example = () => <EmptyOutline />;\n\nexport default Example;\n";

import BackgroundExample from "./variants/background";

const BackgroundSource = "import { EmptyMuted } from \"../examples/empty-background\";\n\nconst Example = () => <EmptyMuted />;\n\nexport default Example;\n";

const meta = {
  component: Empty,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nUse `Empty` for an absent item or an initial state. It includes a subtle dashed boundary and generous spacing by default. Place the icon, title, and description in `EmptyHeader`; place actions or inputs in `EmptyContent` as a sibling. Use `EmptyMedia` without a variant for larger artwork or avatars.\n\n**Import:** `@/registry/erbium/ui/empty`\n\n## Usage\n\n```tsx\nimport { HugeiconsIcon } from \"@hugeicons/react\";\nimport Folder01Icon from \"@hugeicons/core-free-icons/Folder01Icon\";\nimport { Button } from \"@/registry/erbium/ui/button\";\nimport {\n  Empty,\n  EmptyContent,\n  EmptyDescription,\n  EmptyHeader,\n  EmptyMedia,\n  EmptyTitle,\n} from \"@/registry/erbium/ui/empty\";\n\n<Empty>\n  <EmptyHeader>\n    <EmptyMedia variant=\"icon\">\n      <HugeiconsIcon icon={Folder01Icon} />\n    </EmptyMedia>\n    <EmptyTitle>No projects yet</EmptyTitle>\n    <EmptyDescription>Create a project to get started.</EmptyDescription>\n  </EmptyHeader>\n  <EmptyContent>\n    <Button>Create project</Button>\n  </EmptyContent>\n</Empty>;\n```",
      },
    },
  },
} satisfies Meta<typeof Empty>;

export default { ...meta, title: "Feedback & status/Empty",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  className: string;
  mediaVariant: "default" | "icon";
  title: string;
  description: string;
}> = {
  args: {
    className: "",
    mediaVariant: "icon",
    title: "No results",
    description: "Try another search.",
  },
  argTypes: {
    className: { control: "text" },
    mediaVariant: { control: "select", options: ["default", "icon"] },
    title: { control: "text" },
    description: { control: "text" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Avatar: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `EmptyMedia` component to display an avatar in the empty state." },
      source: { code: AvatarSource },
    },
  },
  render: AvatarExample,
};

export const AvatarGroup: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `EmptyMedia` component to display an avatar group in the empty state." },
      source: { code: AvatarGroupSource },
    },
  },
  render: AvatarGroupExample,
};

export const Inputgroup: Story = {
  parameters: {
    docs: {
      description: { story: "You can add an `InputGroup` component to the `EmptyContent` component." },
      source: { code: InputgroupSource },
    },
  },
  render: InputgroupExample,
};

export const InputGroup: Story = {
  parameters: {
    docs: {
      description: { story: "Use an input group as the action in an empty state." },
      source: { code: InputGroupSource },
    },
  },
  render: InputGroupExample,
};

export const Outline: Story = {
  parameters: {
    docs: {
      description: { story: "The default empty state includes a dashed border." },
      source: { code: OutlineSource },
    },
  },
  render: OutlineExample,
};

export const Background: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `bg-*` and `bg-gradient-*` utilities to add a background to the empty state." },
      source: { code: BackgroundSource },
    },
  },
  render: BackgroundExample,
};

import { HugeiconsIcon } from "@hugeicons/react";
import BellIcon from "@hugeicons/core-free-icons/BellIcon";
import RefreshCcwIcon from "@hugeicons/core-free-icons/RefreshCcwIcon";

import { Button } from "@/registry/erbium/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/registry/erbium/ui/empty";

export function EmptyMuted() {
  return (
    <Empty className="h-full bg-muted/30">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <HugeiconsIcon icon={BellIcon} />
        </EmptyMedia>
        <EmptyTitle>No Notifications</EmptyTitle>
        <EmptyDescription className="max-w-xs text-pretty">
          You&apos;re all caught up. New notifications will appear here.
        </EmptyDescription>
      </EmptyHeader>
      <EmptyContent>
        <Button variant="outline">
          <HugeiconsIcon icon={RefreshCcwIcon} data-icon="inline-start" />
          Refresh
        </Button>
      </EmptyContent>
    </Empty>
  );
}

