import { EmptyHeader, EmptyMedia, EmptyTitle, EmptyDescription } from "@/registry/erbium/ui/empty";
import { Empty } from "@/registry/erbium/ui/empty";

const Example = (args: {
  className: string;
  mediaVariant: "default" | "icon";
  title: string;
  description: string;
}) => (
  <Empty className={`w-80 ${args.className}`}>
    <EmptyHeader>
      <EmptyMedia variant={args.mediaVariant}>☆</EmptyMedia>
